(1, 'Bridal Day Package', 'Complete bridal-day styling, start to finish', 'Top Deals', 'bridal-day-package', 'fixed', 9500.00, 61500.00, 52000.00, '[\"Barat \\/ Walima Bridal (Signature Masterpiece)\",\"Eyebrow Precision Threading\",\"Full Face Threading (with Eyebrow Shape)\"]', 'A full bridal day, covered end to end: our signature masterpiece Barat/Walima makeup application by a senior artist, finished with full-face threading and eyebrow shaping so nothing is left to arrange separately on the morning of the event.', 'Booking must be made at least 2 weeks in advance. A consultation is required before the event date. Not combinable with other offers or coupon codes.', 'https://images.unsplash.com/photo-1487412947147-5cebf100ffc2?w=900&h=600&fit=crop', NULL, 'BRIDALDAY', '2026-11-16 10:07:58', '2027-02-17 10:07:58', NULL, NULL, NULL, 0, 0, 1, 1, '2026-11-17 10:07:58', '2026-11-17 10:07:58', NULL),
(2, 'Ultimate Spa Retreat', 'Two signature spa therapies, one relaxed afternoon', 'Top Deals', 'ultimate-spa-retreat', 'fixed', 7500.00, 31500.00, 24000.00, '[\"Full Body Luxury Spa & Massage\",\"Volcanic Hot Stone Spa Therapy\"]', 'Our full-body luxury spa massage paired with volcanic hot stone therapy in the same visit — real muscle release, not just a relaxing hour.', 'Subject to therapist availability. Please arrive 10 minutes early to change. Not combinable with other offers.', 'https://images.unsplash.com/photo-1544161515-4ab6ce6db874?w=900&h=600&fit=crop', NULL, 'SPARETREAT', '2026-11-16 10:07:58', '2027-02-17 10:07:58', NULL, NULL, NULL, 0, 0, 1, 0, '2026-11-17 10:07:58', '2026-11-17 10:07:58', NULL),
(3, 'Hair Revival Bundle', 'High Frequency Hair Voucher', 'Hair Deals', 'hair-revival-bundle', 'fixed', 3750.00, 14250.00, 10500.00, '[\"Hair Botox Restorative Treatment\",\"Classic Blow Dry & Volume\"]', 'A restorative fibre treatment followed by a full blow-dry finish — real repair, not just a styling session.', 'Best results with a follow-up visit within 6 weeks. Not combinable with other offers.', 'https://images.unsplash.com/photo-1560066984-138dadb4c035?w=900&h=600&fit=crop', NULL, 'HAIRVOUCHER', '2026-11-16 10:07:58', '2027-02-17 10:07:58', NULL, NULL, NULL, 0, 0, 1, 0, '2026-11-17 10:07:58', '2026-11-17 10:07:58', NULL),
(4, 'Smoothing Saver', 'X-Tenso smoothing + Hair Botox, together', 'Hair Deals', 'smoothing-saver', 'fixed', 6000.00, 24000.00, 18000.00, '[\"L\'Or\\u00e9al X-Tenso Smooth\",\"Hair Botox Restorative Treatment\"]', 'L\'Oréal X-Tenso smoothing paired with a Hair Botox restorative treatment in the same appointment, for a sleeker finish with less frizz-rebound between washes.', 'Allow up to 5 hours for both treatments. Avoid washing hair for 72 hours afterward. Not combinable with other offers.', 'https://images.unsplash.com/photo-1560066984-138dadb4c035?w=900&h=600&fit=crop', NULL, 'SMOOTHSAVE', '2026-11-16 10:07:58', '2027-02-17 10:07:58', NULL, NULL, NULL, 0, 0, 1, 0, '2026-11-17 10:07:58', '2026-11-17 10:07:58', NULL),
(5, 'Party Glam Duo', 'Signature glam + HD finish, one booking', 'Makeup Deals', 'party-glam-duo', 'fixed', 6000.00, 24000.00, 18000.00, '[\"Signature Glam Party Makeup\",\"HD High-Definition Party Look\"]', 'Two of our most-booked party looks in one package — ideal for back-to-back events or for choosing between two styles at your trial.', 'Both looks must be used within 60 days of purchase. Not combinable with other offers.', 'https://images.unsplash.com/photo-1487412947147-5cebf100ffc2?w=900&h=600&fit=crop', NULL, 'PARTYGLAM', '2026-11-16 10:07:58', '2027-02-17 10:07:58', NULL, NULL, NULL, 0, 0, 1, 0, '2026-11-17 10:07:58', '2026-11-17 10:07:58', NULL),
(6, 'Engagement Ready Package', 'Senior-artist engagement makeup + face threading', 'Makeup Deals', 'engagement-ready-package', 'fixed', 3600.00, 20100.00, 16500.00, '[\"Nikkah \\/ Engagement Makeup (Senior Artist)\",\"Full Face Threading (with Eyebrow Shape)\"]', 'Senior-artist engagement makeup application with full-face threading beforehand, so skin prep and the final look are handled in one visit.', 'Booking requires 1 week notice. Not combinable with other offers.', 'https://images.unsplash.com/photo-1487412947147-5cebf100ffc2?w=900&h=600&fit=crop', NULL, 'ENGAGEREADY', '2026-11-16 10:07:58', '2027-02-17 10:07:58', NULL, NULL, NULL, 0, 0, 1, 0, '2026-11-17 10:07:58', '2026-11-17 10:07:58', NULL),
(7, 'Radiance Ritual', 'Gold Hydra Therapy + gold polisher glow', 'Skin Deals', 'radiance-ritual', 'fixed', 2450.00, 9350.00, 6900.00, '[\"Gold-Infused Hydra Therapy\",\"Radiant Skin Polisher (Gold)\"]', 'A deep-hydration gold facial followed by a micro-exfoliating gold polish for an immediate, event-ready glow.', 'Not recommended within 48 hours of sun exposure. Not combinable with other offers.', 'https://images.unsplash.com/photo-1570172619644-dfd03ed5d881?w=900&h=600&fit=crop', NULL, 'RADIANCE', '2026-11-16 10:07:58', '2027-02-17 10:07:58', NULL, NULL, NULL, 0, 0, 1, 0, '2026-11-17 10:07:58', '2026-11-17 10:07:58', NULL),
(8, 'Glow Prep Combo', 'Skin polish + full-face waxing', 'Skin Deals', 'glow-prep-combo', 'fixed', 675.00, 2975.00, 2300.00, '[\"Radiant Skin Polisher (Gold)\",\"Full Face Waxing (includes Cooling Mask)\"]', 'A gold micro-exfoliating polish paired with full-face waxing and a cooling mask — a genuine pre-event pairing, not two unrelated add-ons.', 'Not combinable with other offers or coupon codes.', 'https://images.unsplash.com/photo-1570172619644-dfd03ed5d881?w=900&h=600&fit=crop', NULL, 'GLOWPREP', '2026-11-16 10:07:58', '2027-02-17 10:07:58', NULL, NULL, NULL, 0, 0, 1, 0, '2026-11-17 10:07:58', '2026-11-17 10:07:58', NULL),
(9, 'Hair + Nails Refresh', 'A cut and a fresh set, same visit', 'Combo Deals', 'hair-nails-refresh', 'fixed', 1250.00, 5750.00, 4500.00, '[\"Junior Stylist Haircut & Finish\",\"Nail Art & Gel Extensions Package\"]', 'A precision cut and finish by one of our junior stylists, paired with a full gel nail art and extension package.', 'Both services must be booked for the same visit. Not combinable with other offers.', 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?w=900&h=600&fit=crop', NULL, 'HAIRNAILS', '2026-11-16 10:07:58', '2027-02-17 10:07:58', NULL, NULL, NULL, 0, 0, 1, 0, '2026-11-17 10:07:58', '2026-11-17 10:07:58', NULL),
(10, 'Pre-Event Polish Combo', 'Threading, skin polish and nails in one visit', 'Combo Deals', 'pre-event-polish-combo', 'fixed', 1200.00, 5950.00, 4750.00, '[\"Radiant Skin Polisher (Gold)\",\"Full Face Threading (with Eyebrow Shape)\",\"Nail Art & Gel Extensions Package\"]', 'Full-face threading, a gold skin polish, and a gel nail art package — the three quick wins clients most often book before an event, bundled into one price.', 'Subject to appointment availability across all three services in a single visit. Not combinable with other offers.', 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?w=900&h=600&fit=crop', NULL, 'PREEVENT', '2026-11-16 10:07:58', '2027-02-17 10:07:58', NULL, NULL, NULL, 0, 0, 1, 0, '2026-11-17 10:07:58', '2026-11-17 10:07:58', NULL),
(11, 'Refer-a-Friend Threading Bonus', 'Bring a friend, get eyebrow threading free', 'Referral Deals', 'refer-a-friend-threading-bonus', 'fixed', 150.00, 150.00, 0.00, '[\"Free Eyebrow Precision Threading with any qualifying booking\"]', 'Refer a friend who books their first appointment with us, and your next eyebrow threading is on the house.', 'Valid on your next visit after your referral completes their first paid appointment. One redemption per referral. Requires a minimum spend of Rs. 3,000 on the same visit.', 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?w=900&h=600&fit=crop', NULL, 'REFERTHREAD', '2026-11-16 10:07:58', '2027-02-17 10:07:58', NULL, NULL, 3000.00, 0, 0, 1, 0, '2026-11-17 10:07:58', '2026-11-17 10:07:58', NULL),
(12, 'Bring a Friend Spa Discount', 'Rs. 1,000 off a full-body spa session', 'Referral Deals', 'bring-a-friend-spa-discount', 'fixed', 1000.00, 15750.00, 14750.00, '[\"Full Body Luxury Spa & Massage\"]', 'Refer a friend and both of you save Rs. 1,000 on a Full Body Luxury Spa & Massage session.', 'Valid once per referred friend. Cannot be combined with other offers.', 'https://images.unsplash.com/photo-1544161515-4ab6ce6db874?w=900&h=600&fit=crop', NULL, 'REFERSPA', '2026-11-16 10:07:58', '2027-02-17 10:07:58', NULL, NULL, NULL, 0, 0, 1, 0, '2026-11-17 10:07:58', '2026-11-17 10:07:58', NULL);
